<?php require_once __DIR__.'/../includes/db.php'; require_once __DIR__.'/../includes/auth.php'; require_login();$stmt=$mysqli->prepare('SELECT b.*,s.slot_number FROM bookings b JOIN slots s ON s.id=b.slot_id WHERE b.user_id=? ORDER BY b.id DESC');$uid=$_SESSION['user']['id'];$stmt->bind_param('i',$uid);$stmt->execute();$rows=$stmt->get_result();$page_title='Booking history';require __DIR__.'/../includes/header.php'; ?>
<h2>Booking history</h2><div class="card shadow-sm border-0 mt-3"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Code</th><th>Slot</th><th>Schedule</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody><?php while($b=$rows->fetch_assoc()):?><tr><td><?=e($b['booking_code'])?></td><td><?=e($b['slot_number'])?></td><td><?=date('d M Y, h:i A',strtotime($b['start_time']))?></td><td>₹<?=number_format($b['parking_amount']+$b['fine_amount'],2)?></td><td><span class="badge text-bg-secondary"><?=e($b['status'])?></span></td><td><a href="booking.php?id=<?=$b['id']?>">View</a></td></tr><?php endwhile;?></tbody></table></div></div><?php require __DIR__.'/../includes/footer.php'; ?>
